-- duckdb: Nepal 2022 and Kenya 2022 women's files from IPUMS DHS extracts converted to parquet.
PRAGMA threads=4;
COPY (SELECT SAMPLE, COUNTRY, YEAR, IDHSPSU, CLUSTERNO, PERWEIGHT, AGE, URBAN, WEALTHQ, EDUCLVL, DEPRESSIONSCORE, DEPRESSIONREFER, GADSCORE, ANXIETYDIAG, INTERNETEVYR, INTERNETMO, CELLPHONSELF, CELLPHONESMART, MOBPHONE FROM read_parquet('data/ipums/dhs/np2022ir.parquet')) TO 'data/extracts/dhs/np2022ir_slim.parquet' (FORMAT PARQUET);
COPY (SELECT SAMPLE, COUNTRY, YEAR, IDHSPSU, CLUSTERNO, PERWEIGHT, AGE, URBAN, WEALTHQ, EDUCLVL, DEPRESSIONDIAG, ANXIETYDIAG, CELLPHONSELF, CELLPHONESMART, MOBPHONE FROM read_parquet('data/ipums/dhs/ke2022ir.parquet')) TO 'data/extracts/dhs/ke2022ir_slim.parquet' (FORMAT PARQUET);
